import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Polish an alternating-corner hexagonal cluster using accepted contact moves."""
    rt3 = np.sqrt(3.0)
    removed = {(2, 0), (0, -2), (-2, 2)}
    axial = [
        (q, r)
        for q in range(-2, 3)
        for r in range(-2, 3)
        if max(abs(q), abs(r), abs(q + r)) <= 2 and (q, r) not in removed
    ]
    best = np.asarray(
        [[q + 0.5 * r, 0.5 * rt3 * r] for q, r in axial], dtype=float
    )

    def objective(x):
        d = x[:, None, :] - x[None, :, :]
        v = np.sum(d * d, axis=2)[np.triu_indices(16, 1)]
        return float(np.min(v) / np.max(v))

    def polish_score(x):
        d = x[:, None, :] - x[None, :, :]
        v = np.sum(d * d, axis=2)
        upper = v[np.triu_indices(16, 1)]
        lo = float(np.min(upper))
        hi = float(np.max(upper))
        return lo / hi, v, lo, hi

    best -= best.mean(axis=0)
    best_value = objective(best)

    for step in (0.12, 0.07, 0.04, 0.022, 0.012, 0.006, 0.003, 0.0015):
        changed = True
        while changed:
            changed = False
            current_value, distances, minimum, maximum = polish_score(best)
            contact_tolerance = max(1.0e-12, minimum * 1.0e-7)
            diameter_tolerance = max(1.0e-12, maximum * 2.0e-5)
            minimum_pairs = []
            diameter_pairs = []
            for i in range(16):
                for j in range(i + 1, 16):
                    if distances[i, j] <= minimum + contact_tolerance:
                        minimum_pairs.append((i, j))
                    if distances[i, j] >= maximum - diameter_tolerance:
                        diameter_pairs.append((i, j))

            for k in range(16):
                force = np.zeros(2, dtype=float)
                for i, j in minimum_pairs:
                    if k != i and k != j:
                        continue
                    other = j if k == i else i
                    delta = best[k] - best[other]
                    length = np.linalg.norm(delta)
                    if length > 1.0e-14:
                        force += delta / length

                partners = []
                for i, j in diameter_pairs:
                    if k == i:
                        partners.append(j)
                    elif k == j:
                        partners.append(i)
                if partners:
                    centroid = np.mean(best[partners], axis=0)
                    delta = centroid - best[k]
                    length = np.linalg.norm(delta)
                    if length > 1.0e-14:
                        force += delta / length

                length = np.linalg.norm(force)
                if length <= 1.0e-14:
                    continue
                candidate = best.copy()
                candidate[k] += step * force / length
                candidate -= candidate.mean(axis=0)
                value = objective(candidate)
                if value > best_value:
                    best = candidate
                    best_value = value
                    changed = True

    best -= best.mean(axis=0)
    return np.asarray(best, dtype=float).reshape(16, 2)

